function shuffleAnimation(send=true){if(Date.now()-lastShuffleCall<450)return;lastShuffleCall=Date.now();if(send&&!screen){const d={type:'shuffleCue',app:'crown52',source:instance};channel?.postMessage(d);if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(d))}shuffleUntil=Date.now()+5000;cardShow.stop();sound.shuffle();sound.setQuiet(false);const deck=$('#deck'),rect=deck.getBoundingClientRect(),scale=rect.width/deck.clientWidth;deck.classList.add('shuffling');if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&rect.width){for(const [i,card]of [...deck.children].entries()){if(!card.animate)continue;for(const old of card.getAnimations())if(old.id==='quick-shuffle')old.cancel();const r=card.getBoundingClientRect(),dx=(rect.left+rect.width/2-r.left-r.width/2)/scale,dy=(rect.top+rect.height/2-r.top-r.height/2)/scale,frames=[{offset:0,transform:'none'}];for(let beat=1;beat<=24;beat++){const t=beat/25,pull=.38+(beat%3)*.2,side=(i+beat)%2?1:-1,x=dx*pull+side*(25+(i*17+beat*11)%65),y=dy*pull+Math.sin(i*1.13+beat*2.1)*38;frames.push({offset:t,transform:`translate3d(${x}px,${y}px,${45+(i+beat)%7*12}px) rotateX(${side*(10+beat%3*5)}deg) rotateY(${(i+beat)%3===0?180:0}deg) rotateZ(${side*(10+(i+beat)%11)}deg) scale(.82)`})}frames.push({offset:1,transform:'none'});card.style.zIndex=String(i+1);const animation=card.animate(frames,{duration:5000,delay:(i%4)*3,easing:'linear'});animation.id='quick-shuffle';animation.finished.then(()=>card.style.zIndex='').catch(()=>{});}}setTimeout(()=>{if(Date.now()>=shuffleUntil-10)deck.classList.remove('shuffling')},5050);}

