function audioUI(){const running=sound.ready&&sound.enabled;$('#soundToggle').textContent=running?'♫ بی‌صدا کردن':sound.enabled?'♫ فعال‌کردن صدا':'♫ صدا خاموش';$('#screenSoundButton').textContent=running?'♫':'♫ فعال‌کردن صدا';$('#screenSoundButton').classList.toggle('ready',running);$('#audioStatus').textContent=running?'فعال':sound.enabled?'منتظر کلیک':'بی‌صدا';$('#soundVolume').value=Math.round(sound.volume*100);$('#ambientSound').checked=sound.ambient;}
function syncAudio(){const s=game.s,id=currentParticipant(),key=id?`${s.round}:${id}`:'';if(key&&key!==lastAudibleTurn&&sound.ready&&sound.enabled){sound.turn();lastAudibleTurn=key}if(!hosted&&previousTurn?.startsWith(`${s.round}:`)&&previousTurn!==key&&s.mode==='tie'&&!s.active&&s.phase==='playing')setTimeout(()=>shuffleAnimation(),550);previousTurn=key;if(s.phase==='lobby'){lastAudibleTurn='';lastWinSound=''}if(s.phase==='won'){const k=`${s.round}:${s.winner}`;if(k!==lastWinSound&&sound.ready&&sound.enabled){sound.win();lastWinSound=k}}sound.setQuiet(!s.active&&!s.manualReveal&&Date.now()>=focusUntil&&Date.now()>=shuffleUntil);audioUI();}
