function renderArrivals(){const entries=(game.s.arrivals||[]).filter(x=>x.endsAt>Date.now()+remoteClock&&x.startedAt<=Date.now()+remoteClock).slice(0,1),key=entries.map(x=>x.id+':'+x.startedAt).join('|');if(key===arrivalSignature)return;arrivalSignature=key;$('#arrivalStack').replaceChildren();for(const person of entries){const bubble=el('div','arrival-bubble');bubble.append(avatar(person));const text=el('div');text.append(el('strong','',person.name),el('small','','خوش آمدید'));bubble.append(text);$('#arrivalStack').append(bubble);}}
function renderShow(){const s=game.s,tl=s.manualReveal||s.active;if(Date.now()<shuffleUntil){cardShow.stop();return}if(s.viewMode==='fun'||!tl||tl.revealAnnounced||(!s.manualReveal&&s.phase==='paused')){cardShow.stop();return}const now=Date.now()+remoteClock,elapsed=Math.max(0,now-tl.startedAt),duration=Math.max(1,tl.revealAt-tl.startedAt),pick=s.manualReveal||s.picks.find(p=>p.id===s.active.pickId);if(!pick||now<tl.startedAt){cardShow.stop();return}if(cardShow.id!==pick.id)sound.shuffle();cardShow.start(pick.id,elapsed,duration,pick.number);const beat=pick.id+':'+Math.floor(elapsed/4000);if(beat!==lastShowBeat){lastShowBeat=beat;sound.turn();}}
function funPicture(person,style){const frame=el('div','fun-portrait');frame.append(avatar(person));if(style){const canvas=el('canvas','comic-canvas');frame.append(canvas);drawFun(canvas,person,style);const stamp=el('span','comic-stamp',style==='royal'?'♛':style==='sketch'?'✎':'★');frame.append(stamp);}return frame;}
function renderFun(){const f=game.s.fun,key=JSON.stringify(f.people);if(key!==funSignature){funSignature=key;const grid=$('#funCards');grid.replaceChildren();const count=52;for(let number=1;number<=count;number++){const person=f.people.find(x=>x.number===number),card=el('button','fun-card'+(person?' occupied':'')+(person?.pending?' pending':''));card.type='button';card.dataset.funNumber=number;card.disabled=screen;if(person){card.append(funPicture(person,person.style),el('strong','',person.name));}else card.append(playingFace(number));card.append(el('span','fun-number',String(number)));card.onclick=()=>{if(person)action(()=>game.funPerson(person,number));else if(hosted&&serverAuthed)socket.send(JSON.stringify({type:'testFunComment',number}));};grid.append(card);}}
const active=f.active,person=active&&f.people.find(x=>x.id===active.personId),hero=$('#funHero'),card=$('#funHeroCard');if(funHeroId!==active?.id){if(funHeroId&&!active){const oldNumber=Number(card.dataset.number),target=$(`[data-fun-number="${oldNumber}"]`),from=card.getBoundingClientRect(),to=target?.getBoundingClientRect();if(to&&from.width&&card.animate){const clone=card.cloneNode(true),original=card.querySelector('canvas'),copy=clone.querySelector('canvas');clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));if(original&&copy)copy.getContext('2d').drawImage(original,0,0);clone.classList.add('fun-return');clone.style.cssText=`position:fixed;left:${from.left}px;top:${from.top}px;width:${from.width}px;height:${from.height}px;z-index:100`;document.body.append(clone);const a=clone.animate([{transform:'none',opacity:1},{transform:`translate(${to.left-from.left}px,${to.top-from.top}px) scale(${to.width/from.width},${to.height/from.height}) rotateY(360deg)`,opacity:.5}],{duration:650,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});a.finished.finally(()=>clone.remove());sound.returnCard();}}
if(active&&person){hero.hidden=false;card.dataset.number=person.number;$('#funHeroPhoto').replaceChildren(funPicture(person,active.kind==='effect'?active.style:null));$('#funHeroName').textContent=person.name;$('#funHeroNumber').textContent='# '+person.number;$('#funHeroCaption').textContent=active.kind==='effect'?'✦':'خوش آمدید';profileEntrance(card,person.number);sound.gift();}funHeroId=active?.id||null;}hero.hidden=game.s.viewMode!=='fun'||!active;}
