function renderDashboard(){const people=game.s.supporters||[],gifters=people.filter(x=>x.coins>0).sort((a,b)=>b.coins-a.coins),likers=people.filter(x=>x.likes>0).sort((a,b)=>b.likes-a.likes),lastGift=people.filter(x=>x.lastType==='gift').sort((a,b)=>b.lastAt-a.lastAt)[0],lastLike=people.filter(x=>x.lastType==='like').sort((a,b)=>b.lastAt-a.lastAt)[0],cells=[['گیفتر برتر',gifters[0],'coins'],['لایکر برتر',likers[0],'likes'],['آخرین گیفتر',lastGift,'coins'],['آخرین لایکر',lastLike,'likes']];const root=$('#supporterDashboard');root.replaceChildren();for(const [title,person,kind]of cells){const tile=el('div','supporter-stat '+kind);const text=el('div');text.append(el('small','',title));if(person){tile.append(avatar(person));text.append(el('strong','',person.name));const amount=el('b','',fa(person[kind]));tile.append(text,amount)}else{text.append(el('strong','','—'));tile.append(text)}root.append(tile);}}
function layoutSupporters(){const arena=$('#arena'),anchor=game.s.viewMode==='fun'?$('#funCards'):$('#deck');if(!arena||!anchor?.offsetHeight)return;const a=arena.getBoundingClientRect(),r=anchor.getBoundingClientRect(),scale=a.width/arena.offsetWidth;if(!scale)return;const top=(r.bottom-a.top)/scale;$('#arrivalStack').style.top=(top+8)+'px';$('#arrivalStack').style.bottom='auto';$('.participant-area').style.top=(top+69)+'px';$('.participant-area').style.bottom='auto';}
const supportLayoutObserver=new ResizeObserver(()=>requestAnimationFrame(layoutSupporters));supportLayoutObserver.observe($('#deck'));supportLayoutObserver.observe($('#funCards'));addEventListener('resize',()=>requestAnimationFrame(layoutSupporters));for(const sheet of document.querySelectorAll('link[rel=stylesheet]'))sheet.addEventListener('load',()=>requestAnimationFrame(layoutSupporters));

